    ctx.fillStyle=wg;ctx.fillRect(0,446,s.worldW,H-446);
    spr(ctx,`th_${th}_plat`,135,442,272,116);
    for(let px=520;px<s.worldW+140;px+=380)spr(ctx,`th_${th}_plat`,px,458,420,124);
