    ctx.strokeStyle="#F472D0";ctx.lineWidth=bandW;ctx.beginPath();ctx.moveTo(SX-15,SY+5);ctx.lineTo(bx-6,by+2);ctx.stroke();
    spr(ctx,"sling_front",SX+4,SY+36,52,84);
